<?php
session_start();require_once 'conexion.php';require_once 'auth.php';asegurarSistemaUsuarios($conexion);exigirRoles(array('ADMINISTRADOR'));require_once 'auditoria_actividad.php';asegurarAuditoriaActividad($conexion);
$desde=trim((string)($_GET['desde']??date('Y-m-d')));$hasta=trim((string)($_GET['hasta']??date('Y-m-d')));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$desde))$desde=date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$hasta))$hasta=date('Y-m-d');$uid=max(0,(int)($_GET['usuario_id']??0));$modulo=strtoupper(trim((string)($_GET['modulo']??'')));$q=trim((string)($_GET['q']??''));
$sql="SELECT fecha,usuario_login,usuario_nombre,usuario_rol,modulo,accion,detalle,referencia,pagina,metodo FROM auditoria_actividad WHERE fecha BETWEEN ? AND ?";$params=array($desde.' 00:00:00',$hasta.' 23:59:59');$types='ss';if($uid>0){$sql.=" AND usuario_id=?";$params[]=$uid;$types.='i';}if($modulo!==''){$sql.=" AND modulo=?";$params[]=$modulo;$types.='s';}if($q!==''){$sql.=" AND (accion LIKE ? OR detalle LIKE ? OR referencia LIKE ? OR usuario_nombre LIKE ?)";$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);$types.='ssss';}$sql.=" ORDER BY fecha,actividad_id LIMIT 100000";$st=$conexion->prepare($sql);$st->bind_param($types,...$params);$st->execute();$r=$st->get_result();
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="auditoria_'.$desde.'_a_'.$hasta.'.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,array('Fecha','Login','Usuario','Rol','Modulo','Accion','Detalle','Referencia','Pagina','Metodo'),';');while($x=$r->fetch_assoc())fputcsv($o,$x,';');fclose($o);$st->close();
?>
